"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3604],{38062:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WreckSalvageService","desc":"Wreck Salvage (permanent party perk `Plunder`, key `WreckSalvageChance`; Hidden\\nuntil enemy ships exist). Each `PerkConfig.WRECK_SALVAGE_STEP` share of an\\n`EnemyShip`\'s `MaxHealth` that its `Health` attribute loses rolls the chance once.\\nEach hit adds `WRECK_SALVAGE_WOOD` Wood + `WRECK_SALVAGE_METAL` Metal to the pool\\nat the ship. The damage source does not matter (cannon, gun or a future weapon).","realm":["Server"],"source":{"line":12,"path":"src/ServerScriptService/WreckSalvageService.server.luau"}}')}}]);